// Bangun body request Groq (vision) dari payload webhook
const input = $input.first().json;
const body = input.body ?? input;

let image = body.image ?? body.image_url ?? body.imageUrl;
if (!image) throw new Error('Field "image" wajib: kirim URL publik atau data URL base64 di body');

// Kalau yang dikirim cuma base64 mentah, bungkus jadi data URL
if (!/^https?:\/\//i.test(image) && !image.startsWith('data:')) {
  image = 'data:image/jpeg;base64,' + String(image).replace(/\s/g, '');
}

const raw = body.participants;
const participants = (Array.isArray(raw) && raw.length ? raw : ['Person 1', 'Person 2'])
  .map(p => (typeof p === 'string' ? p : (p && p.name) || String(p)))
  .filter(Boolean);

return [{
  json: {
    participants,
    groqBody: {
      model: 'gemini-3.5-flash-lite',
      temperature: 0,
      max_tokens: 2000,
      messages: [
        {
          role: 'system',
          content: 'You extract receipt line items. Reply with ONLY a JSON array, no markdown: [{"name":"Item","qty":1,"unit_price":15000,"total":15000}]. Prices are IDR integers.'
        },
        {
          role: 'user',
          content: [
            { type: 'image_url', image_url: { url: image } },
            { type: 'text', text: 'Extract every line item with qty, unit price and line total.' }
          ]
        }
      ]
    }
  }
}];

// Parse jawaban Groq, hitung total & bagian per orang, keluarkan 1 item per peserta
const receipt = $input.first().json;
const raw = (receipt.choices && receipt.choices[0] && receipt.choices[0].message && receipt.choices[0].message.content) || '';

let items = [];
try {
  items = JSON.parse(raw);
} catch (e) {
  const m = raw.match(/\[[\s\S]*\]/);
  if (m) { try { items = JSON.parse(m[0]); } catch (e2) { items = []; } }
}
if (!Array.isArray(items)) items = [];

items = items
  .filter(i => i && i.name && Number(i.total) > 0)
  .map(i => {
    const qty = Number(i.qty) || 1;
    const total = Number(i.total);
    return {
      name: String(i.name),
      qty,
      unit_price: Number(i.unit_price) || Math.round(total / qty),
      total
    };
  });

if (!items.length) throw new Error('Groq tidak mengembalikan item valid. Cek gambar / kuota API key.');

const prep = $('Prepare AI Request').first().json;
const participants = prep.participants;
const total = items.reduce((s, i) => s + i.total, 0);
const perPerson = Math.round(total / participants.length);

// PayPal tidak mendukung IDR -> tagih dalam USD
const IDR_PER_USD = 16000;
const chargeAmount = Math.max(0.01, Math.round((perPerson / IDR_PER_USD) * 100) / 100).toFixed(2);

return participants.map((participant, idx) => ({
  json: {
    participant,
    index: idx,
    participants,
    items,
    total,
    perPerson,
    currency: 'IDR',
    chargeCurrency: 'USD',
    chargeAmount
  }
}));

// Ambil approval URL PayPal + tempel data peserta (urutan sama dengan node Process & Calculate)
const proc = $('Process & Calculate').all();
return $input.all().map((item, i) => {
  const d = item.json || {};
  const p = (proc[i] && proc[i].json) || {};
  const links = Array.isArray(d.links) ? d.links : [];
  const approve = links.find(l => l && l.rel === 'approve');
  return {
    json: {
      participant: p.participant || null,
      amount_idr: p.perPerson || null,
      amount_usd: p.chargeAmount || null,
      order_id: d.id || null,
      status: d.status || null,
      approval_url: approve ? approve.href : null
    }
  };
});

// Ambil order id dari query PayPal (?token=ORDER_ID) dan siapkan URL capture
const q = ($input.first().json.query) || {};
const orderId = q.token || q.order_id || q.orderId;
if (!orderId) throw new Error('Query ?token=<order id> tidak ada. Pastikan return_url diarahkan ke webhook ini.');
return [{ json: { orderId, payerId: q.PayerID || null } }];

// Susun halaman HTML bukti bayar dari respons PayPal capture (execution terpisah, jangan rujuk node workflow lain)
const d = $input.first().json || {};
const unit = (d.purchase_units && d.purchase_units[0]) || {};
const cap = (unit.payments && unit.payments.captures && unit.payments.captures[0]) || {};
const ok = d.status === 'COMPLETED';
const paid = cap.amount ? cap.amount.value + ' ' + cap.amount.currency_code : '-';
const payer = (d.payer && d.payer.name) ? [d.payer.name.given_name, d.payer.name.surname].filter(Boolean).join(' ') : 'Payer';
const who = unit.custom_id || unit.description || '-';
const html = '<!doctype html><html><head><meta charset="utf-8"><title>SplitBill AI</title>'
  + '<style>body{font-family:system-ui,-apple-system,sans-serif;background:#0f1115;color:#e8eaed;'
  + 'display:flex;justify-content:center;align-items:center;min-height:100vh;margin:0;padding:24px}'
  + '.card{background:#181b21;border:1px solid #2a2f3a;border-radius:16px;padding:32px;max-width:480px;width:100%}'
  + 'h1{font-size:22px;margin:0 0 6px}.ok{color:#4ade80}.bad{color:#f87171}'
  + 'dl{display:grid;grid-template-columns:auto 1fr;gap:8px 16px;margin:24px 0 0;font-size:14px}'
  + 'dt{color:#8a93a3}dd{margin:0;text-align:right;color:#e8eaed}small{color:#8a93a3}'
  + '.badge{display:inline-block;background:#14321f;color:#4ade80;border-radius:999px;padding:2px 10px;font-size:12px;margin-left:8px}'
  + '</style></head><body><div class="card">'
  + '<h1 class="' + (ok ? 'ok' : 'bad') + '">' + (ok ? 'Payment captured' : 'Payment ' + (d.status || 'unknown')) + '</h1>'
  + '<small>SplitBill AI &middot; PayPal sandbox' + (ok ? '<span class="badge">PAID</span>' : '') + '</small>'
  + '<dl><dt>Payer</dt><dd>' + payer + '</dd>'
  + '<dt>For</dt><dd>' + who + '</dd>'
  + '<dt>Amount</dt><dd>' + paid + '</dd>'
  + '<dt>Order</dt><dd>' + (d.id || '-') + '</dd></dl>'
  + '</div></body></html>';
return [{ json: { status: ok ? 200 : 402, html } }];
